insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 1, 'What is skin, in the form this course needs it?', '["The pressure drop across the whole reservoir.", "The extra pressure drop near the wellbore, written as a dimensionless number added to the logarithm.", "A measure of how much of the producing interval has actually been perforated, expressed as a fraction of the gross thickness of the sand.", "The ratio of the flowing bottomhole pressure to the average reservoir pressure at the outer drainage boundary of the well."]'::jsonb, 1, 'Occasionally it is less than the ideal rather than more, which is what a negative value records.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 2, 'What does a negative skin mean?', '["The reservoir pressure is below the bubble point.", "The well is taking fluid rather than producing it, so the sign of the pressure drop across the near-wellbore region reverses.", "The completion flows better than the ideal it is compared against.", "The measurement was taken before the well had finished cleaning up, so the recorded value is not yet the stabilised one."]'::jsonb, 2, 'Less resistance than the reference case, not a sign error.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 3, 'Why is the near-wellbore effect written as an additive term?', '["Because it makes the reservoir contribution and the near-wellbore contribution separable.", "Because addition is easier than multiplication.", "Because the logarithm of a radius ratio cannot be evaluated unless a constant is added to it first.", "Because well test software requires the pressure drop to be supplied in that particular algebraic form."]'::jsonb, 0, 'Separability is what lets a perforation skin be computed from geometry with no reservoir model at all.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 4, 'Which of these is NOT one of the contributions to a real well''s total skin?', '["Drilling and completion damage.", "Partial penetration, which applies whenever only part of the producing interval has been opened to flow.", "Turbulence, which is rate dependent and grows as the well is produced harder.", "The absolute permeability of the undamaged rock."]'::jsonb, 3, 'Permeability is a rock property, not a skin component, and it cancels out of the perforation term entirely.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 5, 'A well test measures a total skin of plus three. What does that establish about the perforations?', '["That the perforations are certainly damaged.", "Nothing on its own, because the measurement is a sum over every near-wellbore effect.", "That the perforating gun was run at the wrong depth, so a substantial part of the interval was left unperforated.", "That the crushed zone around each tunnel is at least three times less permeable than the surrounding undamaged rock."]'::jsonb, 1, 'The perforations could be contributing minus two while damage contributes plus five.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 6, 'What can this course legitimately claim to compute?', '["The result of a well test on the completed well.", "The producing rate the well will deliver once it has been perforated with the selected gun and brought on stream.", "The perforation contribution to skin, from geometry, as the published correlation defines it.", "The total near-wellbore pressure drop, including the damage left behind by the drilling fluid during the original drilling of the hole."]'::jsonb, 2, 'It says what the geometry contributes, all else equal, and all else is never equal.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 7, 'What goes into the skin correlation?', '["Four lengths, a phasing angle and two permeability ratios.", "Four lengths and an absolute permeability.", "Three lengths, two angles and the viscosity of the fluid that the completion is expected to produce.", "The full sieve analysis of the formation sand, together with the shot density and the phasing of the selected gun."]'::jsonb, 0, 'Seven inputs, and not one of them is a permeability in millidarcies.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 8, 'Why does the absolute permeability cancel out of the skin?', '["Because the correlation was fitted at one permeability.", "Because the crushed zone around the tunnel is assumed to have the same permeability as the undamaged formation.", "Because permeability is measured in millidarcies and skin is dimensionless.", "Because skin compares two flow geometries that both scale with permeability the same way."]'::jsonb, 3, 'The rock could be one millidarcy or one darcy and every component would be identical.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 9, 'What is the horizontal to vertical permeability ratio doing in the correlation?', '["Setting the absolute level of the rock quality.", "Changing the shape of the flow field by stretching the vertical convergence path.", "Correcting the tunnel length for the fact that a deviated well penetrates the producing interval at an angle.", "Scaling the crushed zone thickness, which is otherwise reported as a fixed fraction of the tunnel radius."]'::jsonb, 1, 'It is an anisotropy, and shape is what a dimensionless skin can see.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 10, 'A crushed zone is five times worse than the rock around it. How does its skin cost depend on the rock quality?', '["It grows in proportion to the rock permeability.", "It falls away as the rock improves, because a better formation can supply the tunnel through a wider area of its wall.", "It does not, because the ratio is a contrast rather than a level.", "It changes only if the tunnel is longer than the crushed shell is thick, which is the usual case for a deep penetrating charge."]'::jsonb, 2, 'A contrast of five costs the same skin at one millidarcy and at a hundred.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 11, 'Where does a permeability in millidarcies actually enter this course?', '["In the underbalance guideline bands, which are indexed by permeability class.", "In the crushed zone skin component.", "In the conversion between shot density expressed per metre and shot density expressed per foot of perforated interval.", "In the productivity ratio, which needs a rate and therefore needs a rock quality to compute that rate from."]'::jsonb, 0, 'Cleaning a tunnel is a transient flushing process, not a steady-state geometry.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 12, 'What is a perforation skin measured against?', '["The same well before it was cased and cemented.", "A reference completion perforated with a standard gun at four shots per foot and sixty degree phasing.", "An identical well in the same reservoir that has been completed open hole rather than cased and perforated.", "An open hole of the same radius with no near-wellbore effect at all."]'::jsonb, 3, 'Not another completion, and not a different gun.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 13, 'Why is that reference case described as imaginary?', '["Because nobody has ever drilled a well of that radius.", "Because a cased well with no perforations does not flow and an uncased one is a different well.", "Because the correlation was derived from a finite element model rather than from any measurement made on a real completion.", "Because open hole completions are no longer permitted by regulators in most of the jurisdictions where the correlation is used."]'::jsonb, 1, 'It is a calculating device, which is a perfectly respectable thing for it to be.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 14, 'How is a negative perforation skin physically possible?', '["The pressure drop reverses direction near the wellbore.", "The crushed zone can be more permeable than the formation when the charge is fired at sufficiently high underbalance.", "The tunnels reach past the wellbore wall into rock the reference hole never touches.", "The convergence of flow into a small number of tunnels is more efficient than radial flow into the full cylinder of the hole."]'::jsonb, 2, 'The effective wellbore radius is genuinely larger than the drilled one, so it is a real stimulation.'),
  ('perfsand', 'intermediate', 'module', 'm01-skin-and-what-it-is-not', 15, 'Which assumption behind the correlation is the one most often forgotten?', '["That the tunnel is open rather than full of debris.", "That the flow is steady and single phase.", "That every perforation in the array has the same length, the same radius and the same orientation as its neighbours.", "That the formation is homogeneous apart from the crushed shell immediately surrounding each of the tunnels."]'::jsonb, 0, 'A tunnel full of charge debris and mud solids is not the modelled geometry, which is what underbalance is for.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 1, 'What ratio does the plane-flow skin component take the logarithm of?', '["The crushed radius divided by the perforation tunnel radius.", "The wellbore radius divided by the effective wellbore radius, which turns negative when the latter is larger.", "The perforation spacing divided by the tunnel length, scaled by the square root of the permeability anisotropy.", "The wellbore radius divided by the sum of the tunnel length and the wellbore radius."]'::jsonb, 1, 'This is the only one of the four components that can come out negative, which is how a perforated well can read as stimulated.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 2, 'For a gun with non zero phasing, how is the effective wellbore radius assembled?', '["A tabulated constant multiplied by the tunnel length alone.", "Half the tunnel length added to the entrance hole diameter of the shaped charge.", "A tabulated constant for the phasing multiplied by the sum of the wellbore radius and the tunnel length.", "The wellbore radius multiplied by an exponential function of the ratio of tunnel length to shot spacing."]'::jsonb, 2, 'Because the two radii are summed, the effective radius grows with penetration close to one for one, times that constant.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 3, 'Which set of three numbers fully determines the plane-flow term?', '["The wellbore radius, the perforation tunnel length and the phasing angle of the gun, and nothing else.", "The shot density, the entrance hole and the crushed zone contrast.", "The wellbore radius, the entrance hole diameter and the vertical permeability.", "The tunnel length, the shot density and the anisotropy, taken together through the two dimensionless groups."]'::jsonb, 0, 'Shot density, entrance hole, anisotropy and crushed zone are all absent from this expression entirely.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 4, 'Going from in line shots to forty five degree phasing on the published high shot density gun is worth over one and four tenths of skin. Why can doubling the penetration not compete with that?', '["Tunnel length does not appear in the plane-flow expression at all.", "Doubling the tunnel length raises the blockage ratio and so cancels its own gain.", "The tunnel length only feeds the crushed-zone factor, so a change in penetration leaves the plane-flow term untouched.", "Penetration enters inside a logarithm, so doubling it moves the term far less than a change of formula does."]'::jsonb, 3, 'More than ninety percent of that one and four tenths of skin sits in the plane-flow component alone.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 5, 'In what order does the module recommend settling the design of a perforating job?', '["Shot density first, then phasing, then penetration, then the rock.", "Penetration first, because it enters both the plane-flow term and the crushed-zone factor.", "Phasing first, then penetration, then shot density, and last the cleanliness of the perforation tunnel.", "Crushed zone treatment first because damage removal costs least, then entrance hole, then phasing, then penetration."]'::jsonb, 2, 'Phasing leads because moving away from in line shots changes the formula rather than only a number in it.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 6, 'How is the dimensionless perforation spacing formed in the converging-flow correlation?', '["Perforation spacing over tunnel length, multiplied by the square root of the permeability anisotropy.", "Perforation spacing divided by the wellbore radius of the completion.", "Tunnel length divided by perforation spacing, then scaled by the entrance hole diameter.", "Tunnel radius over twice the spacing, multiplied by one plus the square root of the inverse anisotropy."]'::jsonb, 0, 'It measures how far fluid must travel vertically compared with how far the tunnel reaches into the rock.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 7, 'Permeability anisotropy enters both dimensionless groups of the converging term. What is the combined effect?', '["The two effects cancel, leaving the term insensitive to anisotropy.", "Only the dimensionless spacing responds, since the radius group uses horizontal permeability.", "The vertical journey lengthens while drainage improves, so the net change depends on the shot density chosen.", "Both groups shift the same way, so greater anisotropy always raises the converging-flow component."]'::jsonb, 3, 'On the published gun, moving from isotropic rock to ten to one roughly triples this component.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 8, 'Which single design input attacks the converging-flow skin most effectively?', '["The entrance hole, because it sets the tunnel radius directly.", "Shot density, because halving the spacing lowers one dimensionless group and raises the other at once.", "The phasing angle, because it selects the tabulated constant used to build the effective wellbore radius.", "The crushed zone contrast, because it multiplies the whole vertical convergence resistance."]'::jsonb, 1, 'Entrance hole moves this term only gently, and tunnel length reaches it through the spacing group.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 9, 'State the dimensionless group that the wellbore blockage skin is an exponential function of.', '["The wellbore radius divided by the sum of the tunnel length and the wellbore radius of the hole.", "The tunnel length divided by the perforation spacing.", "The crushed radius divided by the tunnel radius of the perforation.", "The wellbore radius over the tunnel length, raised to a power fitted separately for each phasing angle."]'::jsonb, 0, 'That ratio runs to nearly one for a tunnel much shorter than the wellbore radius and to nearly zero for a long one.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 10, 'Why do the two fitted blockage constants vary by orders of magnitude with the phasing angle?', '["Because the constants also absorb the shot density of the gun.", "Because the tunnel radius grows with the phase angle chosen for the charge.", "Because a change of phasing changes the effective radius formula, and the fitted constants must follow it.", "Where the shots sit decides how far flow must travel around the wellbore obstruction to reach a tunnel."]'::jsonb, 3, 'At forty five degrees this term is about a ten thousandth of a skin unit on the published high shot density gun.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 11, 'Which completion geometry maximises the wellbore blockage component?', '["A long tunnel in a small hole shot at forty five degrees.", "A short tunnel in a large hole shot in line, pairing the worst ratio with the worst fitted constants.", "A deep penetrating gun run into a hole with a heavily crushed tunnel wall.", "A high shot density gun in an anisotropic reservoir where vertical convergence towards each tunnel is severe."]'::jsonb, 1, 'That describes the through tubing class, where blockage alone contributes about a seventh of the total skin.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 12, 'Name the three factors multiplied together in the crushed-zone skin expression.', '["Shot density, entrance hole diameter and the phasing constant.", "Crushed radius over wellbore radius, the tunnel length and the anisotropy.", "Spacing over tunnel length, the logarithm of crushed radius over tunnel radius, and contrast less one.", "Wellbore radius over effective radius, the square root of anisotropy, and the permeability contrast itself."]'::jsonb, 2, 'The contrast less one form makes the term vanish exactly when the tunnel wall is left undamaged.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 13, 'Doubling the crushed radius shifts the term far less than doubling the severity of the damage. What is the reason?', '["The crushed radius cancels against the tunnel radius in the ratio.", "A thicker shell is always accompanied by a milder contrast in real rock.", "The shell is attached to each perforation, so its cost is fixed by the spacing over tunnel length factor.", "The radius enters through a logarithm while the permeability contrast enters as a strictly linear factor."]'::jsonb, 3, 'A shell five times worse than the rock costs four units of that linear factor, and nine times worse costs eight.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 14, 'After the gun has fired, which component can still be removed by an operation, and how?', '["The blockage term, since a wash removes debris from the wellbore.", "The crushed-zone term, since permeability can be restored by underbalance, an acid wash or a surge tool.", "The plane-flow term, since acid extends the effective reach of every tunnel.", "The converging-flow term, since a later re-perforation at higher shot density lowers the spacing group."]'::jsonb, 1, 'Underbalanced perforating draws the crushed material back out of the tunnel while the tunnel is being formed.'),
  ('perfsand', 'intermediate', 'module', 'm02-the-four-components', 15, 'Across the nine gun catalog at one fixed rock, what makes the crushed-zone swing the second largest of the four?', '["The spacing over tunnel length factor varies enormously from gun to gun even with the damage held fixed.", "Because the crushed radius differs between the charge designs listed.", "Because the logarithm of the radius ratio amplifies small differences between guns.", "Because the permeability contrast assumed for each gun rises with the entrance hole diameter of its charge."]'::jsonb, 0, 'That swing is about one and four tenths of skin, behind the plane-flow term at nearly two and a half units.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 1, 'In the nine gun experiment, what is held identical across every row of the table?', '["The shot density and the phasing angle of each carrier.", "The wellbore radius, the permeability anisotropy and the crushed zone, so only the gun itself varies.", "The completion fluid and the underbalance used when the guns were fired into the formation.", "The tunnel length and the entrance hole diameter, so that the comparison isolates the effect of shot density alone."]'::jsonb, 1, 'Holding the rock fixed is what makes the table a property of the guns rather than of the reservoir it was run in.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 2, 'Why does a set of guns varying in four ways at once still line up into a single ranking?', '["Because the skin correlation is linear in the carrier size.", "Because three of the four inputs were held fixed while only the penetration was allowed to vary.", "Because the ranking was produced by sorting the rows on total skin, which guarantees that any table comes out monotone.", "Because all four inputs improve together as carrier size grows, so nothing pulls against the trend."]'::jsonb, 3, 'Four-way variation usually produces crossings, so this single ranking is a fact about this catalog and not a general rule.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 3, 'Across the nine guns, how wide is the spread in productivity ratio against the ideal?', '["From about three quarters on the smallest carrier to about one point three five on the largest one.", "From about one half up to about two, roughly a fourfold spread.", "From about nine tenths to a little over one, so the nine guns differ hardly at all.", "From well below one half on the smallest gun to more than two on the largest, so the worst gun makes a quarter of the ideal."]'::jsonb, 0, 'A factor near one point eight in deliverability is a large return on a decision taken in an afternoon from a catalog.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 4, 'Which two catalog guns bracket the point where the total skin changes sign?', '["The two largest casing guns in the catalog, both at twelve shots per foot.", "The smallest through-tubing gun and the one sitting immediately above it in the table.", "The two and one eighth inch through-tubing gun, whose total is positive, and the two and seven eighths inch gun.", "The four inch and four and a half inch casing guns, which is where the shot density steps up from six to twelve per foot."]'::jsonb, 2, 'Only three quarters of an inch separates them, but the bigger one is the smallest carrier in the catalog that can be phased.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 5, 'What does a positive perforation skin say about the completed well?', '["It flows worse than an undamaged open hole of the same radius, so the perforations are a net loss.", "The formation around the tunnels has been damaged by the charge.", "The well will not flow at all until the perforations have been cleaned up with acid.", "The tunnels are shorter than the crushed zone is thick, which is the only way the total can come out above zero."]'::jsonb, 0, 'A skin near two on a well whose reservoir logarithm is near eight costs about a fifth of the ideal rate, which is real but survivable.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 6, 'Above the zero line sit two guns sharing three features. Which of the three matters most?', '["Their small carrier diameter, which sets everything else about them.", "They share zero phasing, four shots per foot and short tunnels, and the phasing is the strongest of the three.", "Their big-hole charges, which trade penetration away for entrance hole diameter.", "Their six shots per foot, their sixty degree phasing and their long tunnels, of which the shot density is the strongest."]'::jsonb, 1, 'The crossing coincides exactly with the step from zero to sixty degrees in the catalog, which is why phasing is read as the lever.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 7, 'Sweeping only the phasing angle on one fixed gun, which angle wins and which loses?', '["Ninety degrees is best, and a hundred and eighty is worst.", "A hundred and eighty degrees is best because it drains the rock most symmetrically.", "Forty five degrees is the best of the six tabulated values and zero degrees is by far the worst.", "Sixty degrees is best because it matches the shot density of the casing guns, and forty five is the worst of the six."]'::jsonb, 2, 'The step out of in-line shooting is worth over one and four tenths of a skin unit on the published high shot density gun.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 8, 'How do the five non-zero angles rank against one another?', '["They are identical, since any phasing removes the in-line penalty.", "They improve steadily as the angle widens, so a hundred and eighty is the best of them.", "They rise to a peak at ninety degrees and fall away on either side of it, which is the reason ninety is the usual default.", "The fitted constant falls monotonically from forty five degrees to a hundred and eighty, so more spread is worse."]'::jsonb, 3, 'The whole spread from forty five to a hundred and eighty is only a fraction of the single step out of zero phasing.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 9, 'Why is in-line shooting a discontinuity in the calculation rather than one more step along a trend?', '["The fitted constant for zero degrees happens to be very small.", "The crushed zone term switches to another correlation once the shots line up in one plane.", "It uses a different expression, a quarter of the tunnel length, with the wellbore radius absent.", "The tunnels overlap when they are all fired in the same plane, so the correlation falls back on a purely empirical fit."]'::jsonb, 2, 'Every phased angle instead multiplies a constant by the sum of the wellbore radius and the tunnel length, and it all runs through a logarithm.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 10, 'Penetration and shot density do not reach the same parts of the skin. Which parts does each reach?', '["Penetration enters three of the four components, while shot density reaches only two of them.", "Both enter the same three components, but with opposite signs.", "Penetration enters two components and shot density enters all four of the components.", "Shot density enters three components including the plane flow term, while penetration reaches the converging term alone."]'::jsonb, 0, 'Density moves nothing in the plane flow term or the blockage term, because neither of those contains the shot spacing.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 11, 'Halving the tunnel length hurts more than doubling it helps. What causes the asymmetry?', '["Short tunnels fail to get past the drilling damage zone.", "The tunnel length sits inside a logarithm, so equal multiplicative steps are not equal skin steps.", "The crushed zone shell becomes proportionally thicker as the tunnel is shortened.", "The converging flow term changes sign once the dimensionless spacing rises above one, which happens on short tunnels."]'::jsonb, 1, 'Gains diminish going up and penalties accelerate going down, which is why a marginal gun is worth improving and a good one is not.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 12, 'Given a computed total, how does the catalog say which lever to buy first?', '["If the total is positive then everything helps, and once it is well negative further improvement gets expensive.", "Always buy penetration first, since it enters more components.", "Buy shot density first in every case, because extra holes are cheaper than a bigger charge.", "Buy whichever lever the vendor quotes most cheaply, because the four components respond about equally to either of them."]'::jsonb, 0, 'Short tunnels and low density put the converging and crushed zone terms in charge, so more holes pay best in that regime.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 13, 'Anisotropy is the only rock property the skin calculation takes. What is it and which component feels it?', '["The ratio of tunnel length to shot spacing, in the blockage term.", "The contrast between crushed zone and virgin permeability, felt in the crushed zone term.", "The ratio of vertical to horizontal permeability, which enters the plane flow term through the effective wellbore radius.", "The ratio of horizontal to vertical permeability, and it enters the converging flow term alone."]'::jsonb, 3, 'Typical clastic reservoirs run from about three to about ten, and laminated rock can reach a hundred or more.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 14, 'By which two routes does a higher permeability ratio raise the converging flow term?', '["It raises the crushed zone resistance and the entrance hole loss.", "It doubles the shot spacing and halves the tunnel length within the same expression.", "A square root of it multiplies the dimensionless spacing, and the dimensionless perforation radius shrinks.", "It multiplies the tunnel length by a square root of the ratio and then adds a second logarithm to the plane flow part of the total."]'::jsonb, 2, 'The vertical journey looks longer and the tunnel looks smaller at intercepting vertical flow, so the two effects push the same way.'),
  ('perfsand', 'intermediate', 'module', 'm03-reading-the-catalog', 15, 'A laminated sand shows a high permeability ratio. What is the design response, and where does the model give out?', '["Use a longer charge, and abandon the model below one shot per foot.", "Shoot more holes per foot, and stop trusting a single ratio once shale laminae swallow whole tunnels.", "Raise the underbalance, and treat the correlation as unusable in any rock above ten to one.", "Reduce the shot density to spare the casing, and accept that the ratio already accounts for shale layers that contribute nothing."]'::jsonb, 1, 'Extra shots shorten the vertical convergence path, so the right density is a property of the rock rather than of the gun.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 1, 'Which expression gives the productivity ratio of a perforated completion?', '["The total skin divided by the logarithm of the radius ratio.", "The logarithm of drainage radius over wellbore radius, divided by that same logarithm plus the total skin.", "One minus the total skin divided by the logarithm of the drainage radius over the wellbore radius.", "The flowing bottomhole pressure divided by the average reservoir pressure, corrected for the total skin of the completion."]'::jsonb, 1, 'It falls straight out of the steady radial flow equation, in which rate is proportional to drawdown over the logarithm plus the skin.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 2, 'Why can this number be computed without a permeability, a thickness or a viscosity?', '["Because the model assumes the reservoir is homogeneous.", "Because they are folded into the total skin term along with the drilling damage.", "Because those properties are identical in the actual well and in the ideal reference, so they cancel in the ratio.", "Because the steady radial flow equation drops them once the drawdown is expressed in dimensionless form rather than in field units."]'::jsonb, 2, 'That cancellation is exactly what makes a dimensionless number useful, since it isolates the one thing being compared.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 3, 'The through-tubing gun gives about zero point eight and the high-shot-density gun about one point two seven. What does that pair establish?', '["The second gun flows about fifty nine percent more than the first at the same drawdown, a ratio of ratios.", "The second gun is about twenty seven percent better than the first.", "Neither number can be compared with the other, because each carries a different reference.", "The second gun will produce about fifty nine percent more barrels a day than the first once both wells are on production."]'::jsonb, 0, 'Comparing two guns always means computing both ratios and then comparing those, never reading either figure on its own.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 4, 'In the idealised steady radial picture, what is the drainage radius?', '["The radius of the crushed zone around each perforation tunnel.", "The outer radius of the damaged zone left behind by drilling and completion fluids.", "The distance from the wellbore at which the perforation skin stops contributing to the measured total skin of the completion.", "The radius at which the pressure is the reservoir pressure, beyond which nothing flows to this well."]'::jsonb, 3, 'In a bounded reservoir with several wells it is roughly half the well spacing, and in an unbounded one it never settles.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 5, 'Sweeping the drainage radius from fifty metres to two thousand metres, a factor of forty, does what to the published high-shot-density result?', '["It roughly doubles the ratio across that range.", "It changes the ratio by about a factor of forty as well, since the logarithm is linear in radius.", "It moves the ratio by under a fifth, so the realistic factor of two uncertainty is worth only a few percent.", "It swings the ratio far enough that the drainage radius has to be pinned down before any completion can be compared with another."]'::jsonb, 2, 'The number nobody knows turns out to be the number the answer is least sensitive to, which is a comfortable and uncommon arrangement.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 6, 'Which way does a larger drainage radius push the ratio, and where does that leave perforation design?', '["Away from one, so large drainage areas reward good perforating.", "Towards one from whichever side it starts on, so perforation quality matters most in small drainage areas.", "It has no effect at all, since the drainage radius cancels out of the expression entirely.", "Towards zero, because the reservoir resistance grows without limit while the perforation skin stays fixed at its geometric value."]'::jsonb, 1, 'Infill wells, tight spacing and short-radius horizontal completions are where the gun choice earns the most.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 7, 'A well test reports a total skin. Why is the ratio computed here not a prediction of that measurement?', '["Because well tests measure pressure, not flow geometry.", "Because the test is run after clean-up, when the perforations have already changed.", "Because a well test is run at a single drawdown, whereas the productivity ratio is defined across every drawdown the well will ever see.", "Because the measured total also carries drilling damage, partial penetration, deviation and turbulence."]'::jsonb, 3, 'The perforation term can be strongly negative while the measured total is positive, and the test cannot separate them.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 8, 'Somebody quotes a ratio and says the completion will deliver twenty seven percent more than expected. Which habit prevents that error?', '["State the reference every time the number is quoted, so the reader knows what the comparison is against.", "Round the ratio to one decimal place before reporting it.", "Quote the total skin instead of the ratio, since skin is what a well test returns.", "Recompute the ratio with a larger drainage radius, which will bring the figure back towards one and remove the exaggeration."]'::jsonb, 0, 'If the expectation already assumed a good completion then the uplift is being counted twice, and usually nobody has said which it was.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 9, 'A computed ratio comes out below one. Why is that worth acting on?', '["The completion is worse than an open hole of the same radius, which is a statement in its own right.", "The calculation must contain a sign error somewhere.", "The drainage radius chosen for the calculation was too small to be realistic.", "The reservoir pressure has fallen below the level at which the well can flow to surface without artificial lift installed."]'::jsonb, 0, 'This is one of the few absolute readings the number supports, and it holds whatever the eventual rate turns out to be.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 10, 'At what skin does the expression break, and what does the engine do there?', '["At a skin of zero, where the ratio is exactly one.", "At a skin of minus two, which is the most negative value in the catalog.", "At any negative skin at all, because the model was derived for damaged completions and cannot represent a stimulated wellbore.", "At a skin equal to minus the logarithm the denominator is zero, and the engine refuses to return a number."]'::jsonb, 3, 'Physically that point is where the effective wellbore radius has grown out to the drainage radius, which is a different geometry.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 11, 'Perforations do not reach that bound. What does, and why?', '["Acid washes, because they remove the crushed zone entirely.", "Hydraulic fractures, whose equivalent skin of minus five or minus six can match a small well''s logarithm.", "Nothing does, because the bound sits outside every completion type.", "Deviated wells, because the longer sand face lowers the skin steadily until the denominator of the productivity ratio disappears."]'::jsonb, 1, 'Fracture models use a different formulation precisely because the radial skin form stops applying in that range.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 12, 'Why does the engine refuse near that limit instead of clamping the answer to a large finite ratio?', '["Because clamping would slow the calculation down.", "Because refusing keeps the catalog sweep from running out of memory.", "Because a clamped number gets used, and it would read as a spectacular completion rather than a model failure.", "Because the clamped value would depend on the wellbore radius chosen, and that input is known far less well than the drainage radius."]'::jsonb, 2, 'Naming the condition sends the reader to a formulation that handles it, which a returned number never would.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 13, 'Two completions share a total skin but split it differently between the plane-flow term and the crushed zone. Which treatment helps which?', '["Neither responds, because the total skin is identical.", "A re-perforation run helps the crushed zone case and an acid wash helps the other.", "Both respond equally to an acid wash, since the ratio depends only on the total skin and not on how that total was arrived at.", "An acid wash helps the one whose crushed zone is bad and does nothing for the one with a poor plane-flow term."]'::jsonb, 3, 'This is the clearest case for reporting the four components, because the ratio alone cannot tell the two wells apart.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 14, 'A gas well with a computed skin of minus one tests at plus two when it is produced hard. What is going on?', '["Non-Darcy pressure drop in the tunnels rises with velocity squared and shows up as a skin that grows with rate.", "The perforations have plugged with fines and with scale.", "The gun was run shallow, so only part of the interval was actually opened to flow.", "The drainage radius assumed in the calculation was too large, so the logarithm was overstated and the skin came out negative by mistake."]'::jsonb, 0, 'Everything computed in this course is the low-rate Darcy limit, so a turbulent gas well will always test worse than it calculates.'),
  ('perfsand', 'intermediate', 'module', 'm04-productivity-ratio', 15, 'Which four lines belong alongside a reported productivity ratio?', '["The gun type, the charge weight, the phasing and the shot density.", "The reservoir pressure, the drawdown, the measured rate and the well test skin.", "The four skin components, the interval fraction perforated, a note that it is the Darcy limit, and the date.", "The permeability, the net thickness, the viscosity and the formation volume factor used, so that a rate can be reconstructed later."]'::jsonb, 2, 'The date matters because perforations plug over time, and a ratio of one point three at start-up can be zero point eight two years on.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 1, 'Over what range of the dimensionless perforation radius was the correlation fitted?', '["From zero to one, since the group is dimensionless.", "From about one hundredth to about eighteen hundredths, the span the finite element runs covered.", "From about one hundredth to about ten, which is in fact the span quoted for the dimensionless spacing group instead.", "From about a tenth to about eighteen, one decimal place out from the true span."]'::jsonb, 1, 'Both groups sit in the converging flow term, and both were varied over their stated spans when the finite element results were fitted.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 2, 'The other group with a stated development limit is the dimensionless spacing. What is its limit?', '["It was developed up to about eighteen hundredths.", "It carries no limit at all, because spacing is fixed by shot density and therefore cannot leave the fitted region.", "It was developed up to a value of about ten, so anything above that sits outside the fitted data.", "It was developed up to about two, a limit that several rows in the gun catalog already pass."]'::jsonb, 2, 'No row in the nine gun catalog exceeds the spacing limit, so the single warning that appears comes from the radius group alone.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 3, 'Why is extrapolating a fitted correlation held to be worse than extrapolating a derived law?', '["A fit carries no mechanism, so its exponents have no reason to keep holding past the fitted points.", "A fit uses more digits, and digits accumulate error quickly.", "A fitted correlation is less accurate than a derived law even inside its range, so that same error simply grows once outside it.", "A derived law is validated against field data, which a fitted correlation never is."]'::jsonb, 0, 'A physical law extrapolates because its derivation extrapolates, whereas a fit extrapolates only because nobody stopped it.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 4, 'Outside the stated ranges, what does the engine do with the value it computes?', '["It refuses the request and raises an error instead.", "It clamps the group back to its stated limit, recomputes, and returns the clamped result without further comment.", "It returns the number quietly, on the view that a reader can check the ranges.", "It returns the number together with a warning naming the group involved and the offending value."]'::jsonb, 3, 'Refusal was rejected because the input still describes a real gun in a real well, and silence because an unflagged number gets read like every other number on the sheet.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 5, 'Running the whole catalog of nine guns raises exactly one warning. On which row?', '["The four inch through tubing gun, at about zero point one nine.", "Two rows raise it, the seven inch big-hole casing gun and the deep penetrating casing gun beside it, both on spacing.", "The seven inch big-hole casing gun, whose dimensionless radius reaches about zero point two eight.", "The small in-line through tubing gun, whose low shot density drives the spacing group past ten."]'::jsonb, 2, 'The stated upper limit on that group is about zero point one eight, so the row sits well clear of the fitted data.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 6, 'Why does a big-hole charge turn out to be the class that leaves the development range?', '["It is built to cut a wide entrance hole, and the group divides that radius by only twice the spacing.", "It fires deeper than any other charge in the catalog.", "It is run on larger casing, and the group scales directly with casing diameter, so a seven inch gun exceeds the limit.", "It runs at a lower shot density, which stretches the spacing sitting in the denominator."]'::jsonb, 0, 'A seven tenths of an inch entrance hole at twelve shots per foot is what produces the large ratio, and such guns exist because gravel packing needs wide tunnels.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 7, 'Warnings in a model with a validity range often land on the answers that look best. Why?', '["Because the flagged rows are computed with a different equation.", "Because the warning threshold was tuned to catch high productivity ratios, so an attractive answer triggers it by construction.", "Because extrapolation always biases a power law upward, flattering whatever row it touches.", "Both an attractive answer and a warning come from sitting at the edge of the input space, not the middle."]'::jsonb, 3, 'In this catalog the flagged row is also the one with the lowest total skin and the highest productivity ratio of the nine.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 8, 'Set out the three step response prescribed once a range warning appears on a row.', '["Discard the row, rerun the catalog and report the runner up.", "Notice it, keep the ranking while distrusting the magnitude, then source the number from elsewhere.", "Clamp the group to its limit, recompute the skin, and note the clamped input in the report so it can be reversed.", "Ignore it, since the warning describes the correlation rather than the gun being modelled."]'::jsonb, 1, 'Elsewhere means a vendor''s own modelling, a finite element solution, or a well test on an offset well completed with the same gun.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 9, 'Perforating underbalanced attacks which of the four skin contributions, and by what mechanism?', '["The crushed zone, because reservoir fluid surges into each new tunnel and carries the debris back out.", "The plane flow term, by shortening the path into the rock.", "The converging flow term, because the surge widens the tunnel entrance and so raises the dimensionless perforation radius.", "The wellbore term, since the inrush scours the casing entry clean before production starts."]'::jsonb, 0, 'It is the one component of the four that is not pure geometry, which is why it responds to a pressure condition at all.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 10, 'Which conditions call for more underbalance, according to the published guidance?', '["Higher permeability rock, and oil rather than gas.", "Deeper wells and longer gun strings, since the fluid column has to travel further before the surge reaches the tunnels.", "Tighter rock and oil rather than gas, since oil carries debris far less readily than gas does.", "Tighter rock, because the cleaning flow is slower, and gas rather than oil, by roughly four times."]'::jsonb, 3, 'Too little underbalance leaves a dirty tunnel while too much can destabilise the formation and produce sand on the spot.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 11, 'How are the three permeability classes bounded, and which side of each boundary is inclusive?', '["High above a thousand, moderate above one and low below one.", "High is at or above a hundred millidarcies, moderate runs from ten up to a hundred, and low is below ten.", "High is anything above a hundred millidarcies exclusively, which puts a hundred itself into the moderate class alongside ninety nine.", "High is at or above ten millidarcies, with moderate and low dividing the range beneath it."]'::jsonb, 1, 'The boundaries are inclusive from below, so ninety nine point nine millidarcies is moderate, and each class carries an oil band and a wider gas band.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 12, 'In what form does the engine hand back its underbalance guidance?', '["As a single recommended value in psi, rounded to the nearest hundred.", "As a point value in pascals only, with the class label left for the caller to derive from the permeability it passed in.", "As a range in both pascals and psi, with a class label, an approximate flag and a provenance string.", "As a range in pascals only, since psi is a field unit that the engine deliberately avoids."]'::jsonb, 2, 'A point value would imply a precision the guidance does not have, and a band with provenance invites a decision rather than further arithmetic.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 13, 'One limit is deliberately left out of those bands. Which one, and where does it come from?', '["The minimum needed to clean, which comes from a well test.", "The maximum gun length that can be run in one trip, which comes from the rig and the pressure control equipment.", "The cap against sanding, which follows from rock strength and belongs to the Expert tier calculation.", "The lower bound for gas wells, which the perforation module leaves to a fluid property routine."]'::jsonb, 2, 'The engine composes the cleaning requirement and the sanding cap outside the perforation module rather than pretending one function knows both.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 14, 'Several real effects sit outside this tier altogether. Which set is entirely absent?', '["Crushed zone damage and the converging flow around a tunnel.", "Drilling damage, partial penetration, deviation and turbulence, plus every time dependent process.", "Entrance hole diameter and shot density, which have to be supplied by the reader because no catalog is built into the tier.", "Productivity ratio and its drainage radius dependence, which the Expert tier takes over instead."]'::jsonb, 1, 'A well test sees the sum of every skin term while this course computes one of them, and single phase Darcy flow is assumed throughout.'),
  ('perfsand', 'intermediate', 'module', 'm05-where-the-correlation-stops', 15, 'State the claim the Professional tier actually makes about its own numbers.', '["That the perforation part of skin, for the geometry given, is what the published correlation says.", "That the computed skin matches a well test on the same well.", "That the total skin of the completion is predicted to the precision of the correlation, provided the gun is inside the development range.", "That the gun ranking and the absolute magnitudes are both reliable across the whole catalog."]'::jsonb, 0, 'Anything wider would be borrowed authority, since the correlation supports only that narrow statement, computed to its own precision with the range checked.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'A graduate submits a capstone in which the effective wellbore radius was set to a quarter of the tunnel length, on the grounds that the capstone phasing matches no published gun. What went wrong?', '["Nothing, because both forms return the same radius here.", "That quarter length form belongs to zero phasing alone, and this case is shot at a real angle.", "Nothing is wrong with the form chosen, although the tunnel length should have been halved first because the sheet quotes total penetration.", "The quarter should have been applied to the wellbore radius rather than to the tunnel length."]'::jsonb, 1, 'Picking the tabulated constant for the stated angle is the other half of the step, because the constant changes with every phasing in the table.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Two students disagree over the converging term: one puts the square root of the anisotropy into the dimensionless spacing, the other puts it into the dimensionless radius. Who is right?', '["The second one, because both roots belong to the radius group.", "Neither of them, because anisotropy enters through the crushed zone term and the two converging groups are purely geometric quantities.", "The first one, since spacing carries the root of the anisotropy and the radius carries one plus the root of its reciprocal.", "Both of them, since the two groups multiply together and the roots cancel."]'::jsonb, 2, 'Swapping those two roots is the commonest error in this capstone, and because it moves both groups at once the total still looks plausible.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'A colleague copies the entrance hole diameter from the charge data sheet straight into the tunnel radius box. What does that do to the graded values?', '["It doubles the tunnel radius, so the crushed term and the dimensionless radius both come out too large.", "Nothing at all, because the entrance hole is the tunnel radius.", "It halves the tunnel radius, which shrinks the crushed zone logarithm and drags the dimensionless radius back inside the development range.", "It moves the plane flow term alone, since that is where the tunnel radius sits inside a logarithm."]'::jsonb, 0, 'The radius is half the quoted hole, and the slip also flatters the range check, because the dimensionless radius is the group that decides it.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'A worksheet lists a gun at twelve shots per foot and the spacing box has been filled in with the number twelve. Which correction does the reviewer ask for?', '["Multiply the twelve by the tunnel length to obtain a spacing.", "Leave the twelve where it is, since the correlation groups are dimensionless and any consistent count of shots cancels out of them.", "Convert the figure to shots per metre and enter that count, which is the form the groups expect.", "Invert the density to get a spacing and then convert it, because a spacing is a length rather than a count."]'::jsonb, 3, 'Both halves of the slip are common, and the spacing then feeds the two converging groups and the crushed term together.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'A candidate finds that her three graded skin components do not add up to the graded total, and the shortfall is a few thousandths. Where should she look first?', '["At the blockage term, which is not graded on its own and still belongs in the sum of four components.", "At the productivity ratio, which she has added into the total.", "At rounding, because the engine carries fewer digits in the components than in the total and a small residue is always expected.", "At the crushed zone term, which by convention is reported apart from the total."]'::jsonb, 0, 'The blockage contribution is small at a phased angle and it is never zero, so any sum that leaves it out lands slightly short.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A reviewer opens a report showing a total skin below zero sitting beside a productivity ratio of nought point nine. What does that pairing tell him before he checks any arithmetic?', '["That the drainage radius used must have been very small.", "That one of the two must be wrong, because a negative total always gives a ratio above one.", "That the crushed zone is severe enough to hold the ratio under one even while the total skin stays negative.", "That the well is damaged and the perforations are supplying the damage."]'::jsonb, 1, 'This is one of the three self checks worth writing down before starting, and it costs nothing to apply to a finished sheet.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'An engineer reuses the three hundred metre drainage radius from the lessons while working the capstone. Is the ratio she reports acceptable?', '["Yes, because the ratio hardly moves with drainage radius.", "Yes, provided she notes the substitution, because the logarithm of the radius ratio cancels out of the productivity expression anyway.", "No, the capstone states a drainage radius of its own and the ratio has to be built on the stated value.", "No, but only the four skin components need redoing, not the ratio itself."]'::jsonb, 2, 'Weak sensitivity is an argument about uncertainty in a real well, not a licence to ignore a value the question has supplied.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'A student asks why the dimensionless perforation radius earns a mark of its own when it is merely an intermediate quantity. What is the answer?', '["It is by some way the hardest of the six values to compute.", "It is the number deciding whether this case sits inside the development range of the correlation.", "It is graded because the converging flow term cannot be checked in any other way once the two groups have been combined.", "It is the only one of the six values carrying a physical unit worth checking."]'::jsonb, 1, 'Whether the case falls inside or outside that range is part of what a competent answer knows, even though the mark goes to the value alone.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'The capstone crushed zone is wider than the published cases and less severe. A candidate predicts a larger crushed skin than the lessons showed. Comment on the prediction.', '["Correct, because a wider shell always dominates that term.", "Correct, because the crushed term multiplies the two effects together and a wider shell more than offsets a milder contrast.", "Wrong, because the crushed term depends on the spacing and the tunnel length alone.", "It probably points the wrong way, as the radius enters a logarithm while the contrast enters linearly."]'::jsonb, 3, 'The third factor is the contrast less one, so dropping from a severe contrast to a mild one strips out a large fraction of the term.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'A manager asks why this tier''s results are said to carry across from one well to another and yet to be narrow at the same time. How would you put it to her?', '["Because the results were all fitted at one published rock.", "Because the correlation was solved by finite element, and finite element answers are exact inside their mesh and useless outside it.", "Each result compares two geometries at the same everything else, which is what makes it both clean and limited.", "Because the tier works in dimensionless groups, and such groups are approximate by nature."]'::jsonb, 2, 'The held constant list is exactly where a real well departs from the comparison, so it is worth writing that list beside the answer.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A recruiter asks what someone who has finished this Professional tier can now be trusted to do unaided on a perforating job. Which reply is defensible?', '["Compute a perforation skin in four parts, rank a gun catalogue, and turn a skin into a productivity ratio.", "Predict the skin that a well test on the completion will measure.", "Size a gravel pack from a sieve analysis and set a maximum drawdown from the rock strength along the perforated interval.", "Choose an underbalance from the rock strength and certify the job against sanding."]'::jsonb, 0, 'A full reply also covers stating what the ratio is a ratio of and recognising when a result is an extrapolation of a fit.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A completion shows an excellent perforation skin, but the Expert tier work puts its critical flowing pressure above the pressure the well has to be drawn down to. What follows?', '["It is a good completion, since skin is what governs the rate.", "It is not a good completion, because the cavity the skin assumes fails at the drawdown the well needs.", "It is a good completion so long as the underbalance band is respected, because cleaning the tunnel is what protects the cavity.", "The two results belong to different courses and are reported independently."]'::jsonb, 1, 'The perforation is the cavity, which is why the two halves of the problem live inside one app rather than two.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'A sieve analysis arrives and a junior engineer asks which grain size feeds which piece of hardware in the Expert tier. What do you tell him?', '["The median sizes the gravel by Saucier, the screen gauge follows the gravel, and the slot follows the coarse decile.", "The median alone sets all three, through three fixed multipliers.", "The coarse decile sizes the gravel, the median sets the screen gauge, and the standalone slot width comes from the fines fraction.", "Gravel and screen both come from the median, and the slot width is settled by trial."]'::jsonb, 0, 'Each step is short arithmetic with something surprising in it, and the surprise in the gravel step is that a sand can have no commercial match.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Before an Expert tier sanding sweep can be run on a real well, two data sets have to arrive from other courses. Which two, and what does each supply?', '["Petrophysics supplies porosity and a well test supplies the skin.", "Geomechanics supplies the unconfined strength only, and the drilling course supplies the mud weight programme that caused the damage.", "A production log supplies the inflow profile and a core report supplies the strength.", "Geomechanics supplies stresses, pore pressure and strength on a depth grid, and surveys supply true vertical depth."]'::jsonb, 3, 'The sand control work consumes that profile as data and derives none of it, which is why the two courses are kept apart.'),
  ('perfsand', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Asked how the Expert tier arrives at a maximum drawdown, an engineer sketches a stress calculation at the tunnel wall. Which sequence is she describing?', '["A hoop stress compared against the reservoir pressure alone.", "A fracture gradient from the overburden compared against the mud weight, with the difference read off as the allowable drawdown.", "A hoop stress at the cavity wall set against the strength, giving a critical flowing pressure and then a drawdown.", "An average of the stresses over the interval compared with the strength of the gravel pack."]'::jsonb, 2, 'That calculation is swept along the perforated interval rather than done once, and this course found a real defect inside the sweep.'),
  ('perfsand', 'intermediate', 'final', null, 1, 'A build-up test on a cased and perforated well returns a total skin of plus three, and the completions engineer has computed a perforation skin of minus two for the gun that was run. What do the remaining near-wellbore effects sum to?', '["Zero, because the test already accounts for the perforations.", "Plus three, since a computed perforation skin sits outside the measured total.", "Plus five, because the measured total is the sum of every near-wellbore term and only one of them is known.", "Minus one, because the computed perforation term has to be subtracted from the measured total before damage is read off."]'::jsonb, 2, 'A pressure transient resolves only the sum, so splitting it always needs at least one term computed independently.'),
  ('perfsand', 'intermediate', 'final', null, 2, 'Two wells are completed with the same gun, the same hole size and the same anisotropy, but one produces from one millidarcy rock and the other from one darcy rock. How do their four skin components compare?', '["They are identical, because a dimensionless skin compares two flow geometries that scale alike with permeability.", "They differ by the ratio of the two permeabilities.", "The tighter well shows a larger crushed-zone term and an unchanged plane-flow term.", "They differ, because the correlation carries an absolute permeability inside the converging power law and the shell factor."]'::jsonb, 0, 'Only ratios survive into the skin, which is why one gun choice transfers unchanged across rock qualities.'),
  ('perfsand', 'intermediate', 'final', null, 3, 'Before running the skin calculation a junior engineer asks for a core permeability in millidarcies. Where in this tier is that number actually used?', '["In the crushed-zone term, as the contrast against the shell.", "In the plane-flow term, where it scales the effective wellbore radius against the drilled one.", "Nowhere at all, because every input to this tier is a length, an angle or a ratio and no absolute level enters.", "Only in the underbalance guidance, which classes the rock and returns a band of cleaning drawdown."]'::jsonb, 3, 'Cleaning a tunnel is a transient flushing process, which is a different kind of calculation from a steady geometry.'),
  ('perfsand', 'intermediate', 'final', null, 4, 'A report states that the new gun gives a negative skin because it flows better than the gun previously run in the field. What is wrong with the sentence?', '["Nothing, provided both guns were run in the same interval.", "The sign is measured against an undamaged open hole of the same radius, not against another completion.", "The sign is set by the crushed zone rather than by any comparison of flow.", "It fails because a negative value may only be quoted once a well test has confirmed flow above the ideal rate."]'::jsonb, 1, 'Comparing two guns needs both skins taken against the shared imaginary reference, which then cancels between them.'),
  ('perfsand', 'intermediate', 'final', null, 5, 'A high rate gas well is completed across a laminated sand and the measured skin bears little resemblance to the computed one. Which assumptions have been broken?', '["Single phase Darcy flow and homogeneity, because gas turbulence and shale laminae both sit outside the model.", "Only the steady state assumption, which time alone repairs.", "The periodic array assumption, because gas wells are perforated over longer intervals.", "None of them, since the fitted constants come from a finite element solution that already carries layering and rate."]'::jsonb, 0, 'Non-Darcy pressure drop can exceed the whole perforation skin at rate, and a shot into shale contributes nothing.'),
  ('perfsand', 'intermediate', 'final', null, 6, 'Perforating was carried out overbalanced into a mud filled hole, and a skin was computed from the catalogue geometry the same afternoon. How should that number be described?', '["As the well''s total skin, ready to compare against a test.", "As a conservative estimate, since debris always raises the crushed-zone contrast.", "As a statement about the intended geometry, because the correlation assumes a clean and open tunnel.", "As the actual skin, because the permeability contrast in the crushed term is exactly what represents mud solids left behind."]'::jsonb, 2, 'No permeability ratio describes a tunnel still packed with charge debris, so the assumed shape itself is wrong.'),
  ('perfsand', 'intermediate', 'final', null, 7, 'An operator is puzzled that a well with excellent phased perforations still tests as damaged. Which reading of the two numbers is right?', '["The gun must have misfired across most of the interval.", "A perforation term of minus two sitting under a drilling damage term of plus six leaves a damaged total.", "The perforation skin was computed wrongly, since a phased gun cannot test positive.", "The productivity ratio must be below one, because a well testing as damaged cannot be flowing above its ideal rate."]'::jsonb, 1, 'Perforation quality and drilling damage are separate terms, and only their sum ever reaches the pressure gauge.'),
  ('perfsand', 'intermediate', 'final', null, 8, 'A component sheet reads plane flow minus two point one, converging zero point three, blockage near zero and crushed zone one point four. Which action recovers most?', '["Increasing the shot density, to halve the perforation spacing.", "Changing the phasing angle, since the blockage term is what a phased gun removes.", "Buying a longer charge, because plane flow is the biggest number on the sheet and penetration is what drives it.", "Cleaning the tunnels, because the crushed-zone term is the largest positive contribution on the sheet."]'::jsonb, 3, 'The plane-flow term is already doing its work, and the only positive term worth attacking here is the removable one.'),
  ('perfsand', 'intermediate', 'final', null, 9, 'Gun size forces in-line shots on a slim completion, and the designer proposes to make up the loss with a deeper charge. Will that work?', '["Yes, provided the tunnel length is roughly doubled.", "No, because the phasing loss is a change of formula and penetration only enters inside a logarithm.", "Yes, since penetration reaches three of the four components and phasing reaches one.", "No, because penetration is absent from the plane-flow expression and cannot move the term that phasing controls."]'::jsonb, 1, 'In-line shooting drops the wellbore radius out of the effective radius and swaps in a far smaller constant.'),
  ('perfsand', 'intermediate', 'final', null, 10, 'Two guns are compared in the same anisotropic sand, one firing four shots per foot and the other twelve. Which term carries almost all of the difference?', '["The converging-flow term, because the vertical path between adjacent shots is what a higher density shortens.", "The blockage term, which counts the shots around the hole.", "The plane-flow term, because more shots enlarge the effective wellbore radius.", "The crushed-zone term alone, because the shell around every tunnel is repeated once for each shot that the gun fires."]'::jsonb, 0, 'Density trims the crushed-zone factor as well, but the vertical convergence is where the bulk of the gap sits.'),
  ('perfsand', 'intermediate', 'final', null, 11, 'Someone dismisses wellbore blockage as negligible after seeing it come out near a ten thousandth of a skin unit on a phased gun. Where does that habit fail?', '["On any gun fired into a strongly anisotropic sand.", "On a big-hole gun, whose wide entrance holes raise the blockage ratio sharply.", "On an in-line gun with short tunnels, where the term reaches nearly three tenths of a skin unit.", "On a deeply penetrating casing gun, because a long tunnel drives the blockage ratio towards one and its constants with it."]'::jsonb, 2, 'The two fitted constants swing by three orders of magnitude with the angle, so one ratio costs very different skins.'),
  ('perfsand', 'intermediate', 'final', null, 12, 'Field data suggest the crushed shell on a job is five times worse than the surrounding rock, and a surge tool could bring that down towards two. What is gained?', '["Nothing measurable, since the shell thickness is unchanged.", "The whole crushed-zone term, because any surge restores the original permeability.", "Roughly half of the plane-flow term as well, because a cleaner tunnel behaves as though it were physically longer.", "About three quarters of the crushed-zone term disappears on the published high shot density gun."]'::jsonb, 3, 'That factor is the contrast less one, so moving from five to two takes it from four down to a single unit.'),
  ('perfsand', 'intermediate', 'final', null, 13, 'Damage severity is fixed for all nine catalogue guns, yet their crushed-zone component still spreads over roughly one and four tenths of a skin unit. What causes that?', '["Because the spacing over tunnel length factor varies enormously from the smallest carrier to the largest.", "Because bigger charges crush more rock as they penetrate.", "Because the crushed radius scales with the entrance hole of each charge.", "Because the permeability contrast is quietly recomputed for each gun from its charge weight, which the table hides."]'::jsonb, 0, 'A gun choice therefore changes this component without anyone touching the damage around the tunnel at all.'),
  ('perfsand', 'intermediate', 'final', null, 14, 'A completions group asks in which order to settle a perforating design while every lever is still open. What order does the component ranking support?', '["Cleaning first, then density, then penetration, then phasing.", "Shot density first, because it reaches both of the two positive terms at once.", "Phasing first, then penetration, then shot density, and finally the effort spent cleaning the tunnel.", "Penetration first, because it enters three of the four components and so has the broadest reach of any single input."]'::jsonb, 2, 'In-line shooting is a formula change, which is why nothing else on the sheet competes with settling the angle.'),
  ('perfsand', 'intermediate', 'final', null, 15, 'A vendor offers a slimline carrier loaded with an unusually deep charge, which the nine gun table has no equivalent of. What happens to the ranking by carrier size?', '["It can break, because that table ranks only where four inputs happen to improve together in step.", "It holds, since carrier size sets the penetration available.", "It holds, because the correlation ranks guns on phasing before anything else is considered.", "It breaks in every case, because a slim carrier cannot phase its shots and so always falls above the crossing."]'::jsonb, 0, 'Monotonicity is a property of this catalogue rather than of the correlation that produced the numbers.'),
  ('perfsand', 'intermediate', 'final', null, 16, 'Only three quarters of an inch separates the last gun with a positive total from the first with a negative one. What makes them so different?', '["The larger gun carries a much heavier charge per shot.", "The smaller gun is run through tubing and therefore into a live well.", "The larger of the two is the smallest carrier that can phase its shots away from one single line.", "They sit on opposite sides of the development range, so one of the pair is flagged as extrapolated and one is not."]'::jsonb, 2, 'Phasing changes the expression for the effective wellbore radius, which is why the crossing lands exactly there.'),
  ('perfsand', 'intermediate', 'final', null, 17, 'Deferring a workover means accepting a through-tubing gun whose total skin is around plus two on a well whose reservoir logarithm is near eight. What is the cost?', '["Around double the ideal rate, since skin adds to the logarithm.", "Around a fifth of the ideal rate, which prices the trade without deciding whether it is worth taking.", "Around two per cent, because a skin of two is small against a logarithm of eight.", "The well is ruined, because any positive perforation skin means the completion flows worse than an open hole ever would."]'::jsonb, 1, 'Whether a deferred workover is worth that loss is an economic question the calculation cannot settle.'),
  ('perfsand', 'intermediate', 'final', null, 18, 'A colleague argues that shooting a hundred and eighty degrees apart drains the rock most symmetrically and should therefore win the phasing sweep. What does the sweep show?', '["Ninety degrees wins, with the rest close behind it.", "The colleague is right, since the widest spread gives the largest effective radius.", "Every phased angle ties, because the tabulated constant is the same for each angle other than the in-line case.", "Forty five degrees wins, and the fitted constant falls steadily from there out to a hundred and eighty."]'::jsonb, 3, 'Those constants come from a finite element solution, so an argument from symmetry cannot settle the question.'),
  ('perfsand', 'intermediate', 'final', null, 19, 'An engineer wants to know which of a longer charge or more shots per foot touches more of the calculation. What does the component structure say?', '["Extra shots, which reach every term except the blockage one.", "The longer charge, since it enters three of the four components while extra shots enter only two.", "They reach the same three components and differ only in magnitude.", "Extra shots, because density appears in the plane-flow term through the spacing and in the blockage ratio as well."]'::jsonb, 1, 'Reach is not the same as size, and on a gun with short tunnels the narrower lever can still help most.'),
  ('perfsand', 'intermediate', 'final', null, 20, 'Moving from an isotropic sand to a ten to one permeability ratio roughly triples the converging term on the published high shot density gun. Why is that move worse elsewhere?', '["Because low density guns carry a larger blockage constant.", "Because on a low density gun the same term already dominates, so tripling it drags the total a long way.", "Because the anisotropy also enters the crushed-zone term through the spacing.", "Because that published gun is the only row in the table whose converging term an anisotropy is allowed to touch."]'::jsonb, 1, 'The published gun keeps a comfortably negative total through the change because its converging term started small.'),
  ('perfsand', 'intermediate', 'final', null, 21, 'A shot lands entirely within a shale lamina in a thinly bedded sand. Can a larger anisotropy ratio represent that inside the correlation?', '["No, because such a perforation is absent rather than poorly draining, and no ratio describes an absence.", "Yes, provided the ratio is raised above one hundred.", "Yes, since that ratio is exactly what carries layering into the converging term.", "No, but the crushed-zone term absorbs it instead, because a shot into shale simply raises the effective contrast."]'::jsonb, 0, 'This is the point at which a perforation skin correlation stops being the right tool for the reservoir.'),
  ('perfsand', 'intermediate', 'final', null, 22, 'A casing gun gives a total perforation skin of about minus two in a well whose logarithm of drainage over wellbore radius is close to eight. What ratio follows?', '["Roughly minus two, since the skin carries straight through.", "Roughly one and a third, because the negative skin shrinks the denominator while the numerator holds.", "Roughly four fifths, because a skin of two always costs a fifth of the ideal.", "Roughly one and a quarter, because that skin has to be added to the logarithm in the numerator before dividing."]'::jsonb, 1, 'The numerator is the ideal well and only the denominator carries the completion, so the sign flips the answer.'),
  ('perfsand', 'intermediate', 'final', null, 23, 'An appraisal well has no offsets, so its drainage radius could be wrong by a factor of five. Should the productivity ratio be withheld until that is pinned down?', '["Yes, because the ratio scales directly with the drainage radius.", "Yes, because an unknown radius pushes the result towards the bound on negative skin.", "No, because the drainage radius cancels between numerator and denominator in exactly the way a permeability does.", "No, since a factor of forty moves the published result by under a fifth and a realistic factor of two by a few per cent."]'::jsonb, 3, 'The one input nobody knows is the one the answer is least sensitive to, which is an unusually comfortable arrangement.'),
  ('perfsand', 'intermediate', 'final', null, 24, 'Two candidate wells are on the desk, an infill on tight spacing and a single producer draining two kilometres. Where does care over perforating buy more?', '["The single producer, which has more rock to drain.", "Neither, since the ratio is dimensionless and therefore free of any spacing.", "The infill, because a small drainage area leaves the near wellbore term a larger share of the resistance.", "The single producer, because a large logarithm magnifies the skin instead of diluting it and so multiplies any loss."]'::jsonb, 2, 'A larger drainage radius pushes the ratio towards one from whichever side it sits, diluting good and bad alike.'),
  ('perfsand', 'intermediate', 'final', null, 25, 'A stimulation engineer feeds an equivalent skin of minus six for a long fracture into the same expression, in a well whose logarithm is about six and a half. What happens?', '["The engine refuses, because the denominator is approaching zero and the model has left its own range.", "The ratio comes back at about thirteen, which is the answer.", "The engine clamps the result and reports a large but finite ratio.", "It returns a negative ratio, which correctly signals that the fracture is draining rock beyond the drainage radius."]'::jsonb, 0, 'Fracture models use a different formulation precisely because this one runs to infinity at a reachable input.'),
  ('perfsand', 'intermediate', 'final', null, 26, 'A completion report quotes a ratio of one point two seven and promises twenty seven per cent above expectation. Which single habit would have prevented the mistake?', '["Rounding the ratio to one decimal place before reporting it.", "Naming the reference each time the number is quoted, so a reader knows what it was compared against.", "Reporting the four components underneath the ratio rather than the ratio alone.", "Quoting a rate in barrels a day instead, because a dimensioned number cannot be double counted the way a ratio can."]'::jsonb, 1, 'If the expectation already assumed a decent completion then the gain is quietly being counted a second time.'),
  ('perfsand', 'intermediate', 'final', null, 27, 'Comparing the two published guns, one lands near zero point eight and the other near one point two seven. How should that pair be reported to a client?', '["As a gain of about forty seven per cent over the poorer gun.", "As proof that the better gun delivers twenty seven per cent above the field average.", "As two separate comparisons against an imaginary open hole, which cannot be combined into a statement about the pair.", "As one gun flowing about fifty nine per cent more than the other when both are drawn down equally."]'::jsonb, 3, 'Both carry the same imaginary reference, so dividing one by the other cancels that reference cleanly.'),
  ('perfsand', 'intermediate', 'final', null, 28, 'A gas well was handed over with a ratio of one point three at start-up and is measured well below it two years later. Which omissions could account for that?', '["An error in the drainage radius used at handover.", "A change in the crushed zone contrast, which alone sets the behaviour in time.", "Turbulence with rate and plugging over time, neither of which this geometry calculation carries at all.", "Nothing in that list, because a steady state number does not change once the well has been put on production."]'::jsonb, 2, 'What was computed is the low rate Darcy limit on the day the completion geometry was fixed.'),
  ('perfsand', 'intermediate', 'final', null, 29, 'Scanning the nine row table for the lowest total skin lands a reader on the seven inch big-hole gun. What has the reader also landed on?', '["The only row shot at zero phasing in the whole table.", "The row with the shortest tunnel, which is why its blockage term is large.", "The only flagged row, whose dimensionless perforation radius sits well above the fitted upper limit.", "A row exceeding both stated development limits at once, which is why it produces the most attractive answer of the nine."]'::jsonb, 2, 'Attractive answers and warnings tend to arrive together, because both come from the edge of the input space.'),
  ('perfsand', 'intermediate', 'final', null, 30, 'Of the nine rows only one leaves the development range, and it is a gravel pack gun. What about that class of charge causes it?', '["A wide entrance hole at twelve shots per foot makes the tunnel radius large against twice the spacing.", "Its tunnels are far shorter than any other row in the table.", "Its phasing is not one of the six angles the correlation tabulates constants for.", "Its charge sits in a carrier too large for the wellbore radius the correlation was fitted against, so the geometry is out."]'::jsonb, 0, 'Big-hole charges exist for gravel packing, so the flag lands on an ordinary and necessary gun rather than an exotic one.'),
  ('perfsand', 'intermediate', 'final', null, 31, 'A range warning has appeared beside the most attractive gun on a sheet that is due with a client tomorrow. What is the prescribed response?', '["Drop the row and recommend the next best gun instead.", "Notice it, keep the ranking, distrust the magnitude, and source a number elsewhere if the magnitude matters.", "Report the value unchanged, since the warning concerns the input rather than the output.", "Rerun the row with the dimensionless radius clipped to the stated limit, which brings the case back inside the range."]'::jsonb, 1, 'The physical argument that a wide long tunnel drains well does not lean on the correlation, so the order survives.'),
  ('perfsand', 'intermediate', 'final', null, 32, 'Someone points out that a power law with fitted exponents will happily return a number for any positive input. Why is that not reassuring?', '["Because power laws are unstable for very small arguments.", "Because the finite element solution was itself only approximate near the range limits.", "Because a fitted exponent changes sign outside the range it was developed over, which reverses the term entirely.", "Because a fit has no mechanism in it, so nothing carries the curve beyond the points it was drawn through."]'::jsonb, 3, 'A derived law extrapolates because its derivation does, and that is exactly what a fitted correlation lacks.'),
  ('perfsand', 'intermediate', 'final', null, 33, 'The underbalance band for a friable sand looks achievable, so the job is designed straight from it. Which limit has been left out of that design?', '["The cap set by rock strength, above which the surge that cleans a tunnel starts producing sand.", "The lower limit, which the band already states for each class.", "The gun clearance limit, which decides whether the carrier can be run at all.", "No limit is missing, because the published bands were built from strength tests and already carry the sanding cap."]'::jsonb, 0, 'That cap belongs to the Expert tier''s calculation, and the engine composes the two outside the perforation module.'),
  ('perfsand', 'intermediate', 'final', null, 34, 'Two jobs are planned for the same week, one on a tight gas sand and one on a permeable oil sand. Which needs the greater underbalance, and why?', '["The oil sand, because liquid carries debris better than gas.", "Neither, since the guidance is indexed on the gun rather than on the rock.", "The gas sand, because tighter rock cleans more slowly and the gas bands run several times the oil ones.", "The gas sand, because gas expands as it surges and so the guidance holds its underbalance below the oil case."]'::jsonb, 2, 'Too much underbalance can produce sand on the spot, and that upper limit is not what these bands carry.'),
  ('perfsand', 'intermediate', 'final', null, 35, 'A core report gives ninety nine point nine millidarcies and the log analyst calls the interval high permeability. Is that the right class?', '["Yes, because anything that close to a hundred rounds into the class.", "Yes, because the classes are advisory and their boundaries carry no consequence.", "No, it falls in the low permeability class, because a moderate band is entered only above one hundred millidarcies.", "No, it falls in the moderate class, because the boundary at one hundred is inclusive from below."]'::jsonb, 3, 'Getting the class wrong moves the returned band, which is why each boundary states the side that is inclusive.'),
  ('perfsand', 'intermediate', 'final', null, 36, 'A capstone attempt takes the entrance hole diameter from the gun sheet and enters it where a tunnel radius is wanted. Which values go wrong?', '["Only the plane-flow term, which carries the tunnel geometry.", "The converging and crushed-zone terms, because both are built on the tunnel radius rather than the hole.", "Every one of the four, since a tunnel radius runs right through the whole correlation.", "None of them, because the correlation takes an entrance hole diameter directly and halves it internally before use."]'::jsonb, 1, 'The radius is half the entrance hole, and the dimensionless perforation radius is graded on its own for that reason.'),
  ('perfsand', 'intermediate', 'final', null, 37, 'Shot density arrives from the catalogue in shots per foot while the correlation wants a spacing in metres. What has to happen to it?', '["Multiply the density by the tunnel length to obtain a spacing.", "Nothing, because both dimensionless groups take the density directly.", "Convert the density into shots per metre and then invert it, since spacing is the reciprocal of density.", "Convert into shots per metre and use it as it stands, because dimensionless groups need no inversion of any kind."]'::jsonb, 2, 'Two of the four components carry the spacing, so a density left uninverted moves more than one graded value.'),
  ('perfsand', 'intermediate', 'final', null, 38, 'A worked capstone applies a quarter of the tunnel length as the effective wellbore radius, although the case specifies a real phasing angle. What follows?', '["The plane-flow term comes out badly wrong, because a phased case adds the wellbore radius before scaling.", "The blockage term is wrong, since it shares the same constants.", "Nothing changes, because the two formulas agree closely at small angles.", "Only the productivity ratio moves, since an effective wellbore radius appears nowhere else among the four terms."]'::jsonb, 0, 'Dropping the wellbore radius out of that sum is a large change, and it then passes through a logarithm.'),
  ('perfsand', 'intermediate', 'final', null, 39, 'Three components are computed carefully and summed, and the total is handed in. Why does the work fail its first self check?', '["Because the crushed-zone term is graded on its own instead.", "Because a total is only checked against the productivity ratio and never against its parts.", "Because these components multiply rather than add, so a sum could never reproduce the graded total in any case.", "Because the blockage term stays small at a real phasing angle and yet it is never exactly zero."]'::jsonb, 3, 'Checking that the parts add to the whole is the cheapest of the three checks and it catches this immediately.'),
  ('perfsand', 'intermediate', 'final', null, 40, 'The commonest error in the converging term is getting two square roots the wrong way round. Which group takes which?', '["Both groups carry the root of the reciprocal anisotropy.", "The spacing group carries no root at all and the radius group carries both of them.", "The spacing group takes the root of the reciprocal and the radius group one plus the root of the anisotropy itself.", "The spacing group carries the root of the anisotropy and the radius group the root of its reciprocal."]'::jsonb, 3, 'The two groups pull the same way, so a swap can leave the term looking plausible while it is quietly wrong.'),
  ('perfsand', 'intermediate', 'final', null, 41, 'An Expert tier run returns a critical drawdown below what the well needs, on a completion whose perforation skin is excellent. How should the two be read?', '["Together, because the flow calculation assumes a cavity that the strength calculation says will fail.", "Separately, since one is a flow result and one is mechanical.", "The skin governs, because a productivity ratio above one settles the completion choice.", "The drawdown result should be discarded, because a negative perforation skin means the cavity is stable by construction."]'::jsonb, 0, 'That is why the two halves live in one app rather than two, and why neither is ever quoted on its own.'),
  ('perfsand', 'intermediate', 'final', null, 42, 'Planning the Expert tier work reveals inputs this course never derives for itself. Which two courses supply them?', '["Stimulation Design for the fracture half length and its skin.", "Completion Design for the hardware and Well Integrity for the long term.", "Geomechanics for the stress and strength profile, and Well Design and Surveys for the depth conversion.", "Neither, because the Expert tier derives its own overburden, horizontal stresses and unconfined strength from a sieve."]'::jsonb, 2, 'The tier consumes that profile as data on a depth grid rather than deriving any part of it from first principles.');
